import React, { useEffect, useState } from "react";
import axios from "axios";

function QuizStudent() {
  const studentId = localStorage.getItem("user_id");

  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState({});
  const [current, setCurrent] = useState(0);
  const [score, setScore] = useState(null);
  const [timeLeft, setTimeLeft] = useState(60); // seconds
  const [submitted, setSubmitted] = useState(false);

  // 🔥 Fetch quiz
  useEffect(() => {
    axios.get("http://127.0.0.1:8000/quiz/1")
      .then(res => setQuestions(res.data.questions || []));
  }, []);

  // 🔥 Timer
  useEffect(() => {
    if (submitted) return;

    if (timeLeft === 0) {
      submitQuiz();
      return;
    }

    const timer = setInterval(() => {
      setTimeLeft(prev => prev - 1);
    }, 1000);

    return () => clearInterval(timer);
  }, [timeLeft, submitted]);

  const handleSelect = (qId, opt) => {
    setAnswers({
      ...answers,
      [qId]: opt
    });
  };

  const submitQuiz = async () => {
    if (submitted) return;

    const res = await axios.post(
      "http://127.0.0.1:8000/submit-quiz",
      {
        quiz_id: 1,
        student_id: parseInt(studentId),
        answers
      }
    );

    setScore(res.data.score);
    setSubmitted(true);

    window.dispatchEvent(new Event("plannerUpdated"));
  };

  if (questions.length === 0) return <p>Loading...</p>;

  const q = questions[current];

  return (
    <div>
      <h2>Quiz 🚀</h2>

      {/* Timer */}
      <h3 style={{ color: "red" }}>
        Time Left: {timeLeft}s
      </h3>

      {/* Question */}
      <div style={card}>
        <h4>
          Q{current + 1}. {q.question}
        </h4>

        {[q.option1, q.option2, q.option3, q.option4].map((opt, i) => {
          let bg = "#fff";

          if (submitted) {
            if (opt === q.correct_answer) bg = "#c8e6c9"; // green
            else if (answers[q.id] === opt) bg = "#ffcdd2"; // red
          } else if (answers[q.id] === opt) {
            bg = "#d1c4e9";
          }

          return (
            <div
              key={i}
              onClick={() => !submitted && handleSelect(q.id, opt)}
              style={{ ...option, background: bg }}
            >
              {opt}
            </div>
          );
        })}
      </div>

      {/* Navigation */}
      <div style={{ marginTop: "10px" }}>
        <button
          disabled={current === 0}
          onClick={() => setCurrent(current - 1)}
        >
          Prev
        </button>

        <button
          disabled={current === questions.length - 1}
          onClick={() => setCurrent(current + 1)}
        >
          Next
        </button>
      </div>

      {/* Submit */}
      {!submitted && (
        <button onClick={submitQuiz} style={submitBtn}>
          Submit Quiz
        </button>
      )}

      {/* Result */}
      {submitted && (
        <h3 style={{ color: "green" }}>
          Score: {score} / {questions.length}
        </h3>
      )}
    </div>
  );
}

/* Styles */
const card = {
  background: "#fff",
  padding: "20px",
  borderRadius: "10px",
  marginBottom: "15px"
};

const option = {
  padding: "10px",
  margin: "5px 0",
  border: "1px solid #ccc",
  borderRadius: "8px",
  cursor: "pointer"
};

const submitBtn = {
  marginTop: "15px",
  background: "#7b1fa2",
  color: "#fff",
  padding: "10px",
  border: "none",
  borderRadius: "8px"
};

export default QuizStudent;
